import Link from 'next/link'

const categories = [
  { slug: 'featured', label: 'Featured products' },
  { slug: 'sale', label: 'Products on sale' },
]

export default function Home() {
  return (
    <main>
      <h1>Shop by category</h1>
      <ul>
        {categories.map((category) => (
          <li key={category.slug}>
            <Link href={`/catalog?category=${category.slug}`}>
              {category.label}
            </Link>
          </li>
        ))}
      </ul>
    </main>
  )
}
import { Suspense } from 'react'
import { getProducts } from '@/lib/data'

type CatalogSearchParams = Promise<{ category?: string }>

export default function CatalogPage({
  searchParams,
}: {
  searchParams: CatalogSearchParams
}) {
  return (
    <main>
      <h1>Catalog</h1>
      <Suspense fallback={<p>Loading category...</p>}>
        <CategoryResults searchParams={searchParams} />
      </Suspense>
    </main>
  )
}

async function CategoryResults({
  searchParams,
}: {
  searchParams: CatalogSearchParams
}) {
  const { category = 'featured' } = await searchParams
  const products = await getProducts(category)

  return (
    <section>
      <h2>{category === 'sale' ? 'Products on sale' : 'Featured products'}</h2>
      <ul>
        {products.map((product) => (
          <li key={product}>{product}</li>
        ))}
      </ul>
    </section>
  )
}
import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'Product catalog',
  description: 'Browse products by category',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}

